TLM.f("Sancti/04-13",{"officium":"S. Hermenegildi Martyris","rule":["vide C2;"],"fallback":"Commune/C2","from":{"Introitus":"Commune/C2","Lectio":"Commune/C2","Graduale":"Commune/C2","GradualeP":"Commune/C2","Tractus":"Commune/C2","Offertorium":"Commune/C2","Communio":"Commune/C2"},"sections":{"Introitus":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."}],"Oratio":[{"k":"text","la":"Deus, qui beátum Hermenegíldum Mártyrem tuum cœlésti regno terrénum postpónere docuísti: da, quǽsumus, nobis; ejus exémplo cadúca despícere atque ætérna sectári."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 14:26-33"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis: Si quis venit ad me, et non odit patrem suum, et matrem, et uxórem, et fílios, et fratres, et soróres, adhuc autem et ánimam suam, non potest meus esse discípulus. Et qui non bájulat crucem suam, et venit post me, non potest meus esse discípulus. Quis enim ex vobis volens turrim ædificáre, non prius sedens cómputat sumptus, qui necessárii sunt, si hábeat ad perficiéndum; ne, posteáquam posúerit fundaméntum, et non potúerit perfícere, omnes, qui vident, incípiant illúdere ei, dicéntes: Quia hic homo cœpit ædificáre, et non pótuit consummáre? Aut quis rex itúrus commíttere bellum advérsus álium regem, non sedens prius cógitat, si possit cum decem mílibus occúrrere ei, qui cum vigínti mílibus venit ad se? Alióquin, adhuc illo longe agénte, legatiónem mittens, rogat ea, quæ pacis sunt. Sic ergo omnis ex vobis, qui non renúntiat ómnibus, quæ póssidet, non potest meus esse discípulus."}],"Offertorium":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum: et constituísti eum super ópera mánuum tuárum, Dómine."}],"Secreta":[{"k":"text","la":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:24"},{"k":"text","la":"Qui vult veníre post me, ábneget semetípsum, et tollat crucem suam, et sequátur me."}],"Postcommunio":[{"k":"text","la":"Da, quǽsumus, Dómine, Deus noster: ut, sicut tuórum commemoratióne Sanctórum temporáli gratulámur offício; ita perpétuo lætémur aspéctu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ee67b476e9f36f4d":{"t":"Ps 63, 3, Ps 63, 2\n(Ps 63, 3) Zaštitio si me, Gospodine, od skupa zlikovaca, <i>aleluja</i>,\nod bezbožnoga mnoštva, <i>aleluja</i>, <i>aleluja</i>!\n(Ps 63, 2) Usliši, Gospodine, moju molitvu, jer se tebi molim. Ne daj da se moja duša straši neprijatelja!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 63, 3) Zaštitio si me, Gospodine, od skupa zlikovaca, <i>aleluja</i>,\nod bezbožnoga mnoštva, <i>aleluja</i>, <i>aleluja</i>!","kn":"(Ps. 63, 2). Štiti me. Bože, od gomile zloitvora. Alelujaod. mnoštva bezbožnoga, aleluja, aleluja. Usliši, Bože, moju molitvu, jer u Tebe se uzdam. izbavi moju dušu do straha neprijateljskoga. Slava Ocu . . . Štiti me . . , <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 566–567 (snimka 284) (OCR)"},"40a99f4815257532":{"t":"<i>Pomolimo se</i>.\nBože, koji si poučio blaženoga Hermenegilda mučenika svoga da manje cijeni zemaljsko kraljevstvo nego nebesko, daj nam molimo, da po njegovu primjeru preziremo prolazna dobra i tražimo nebeska.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženoga Hermenegilda, mučenika svoga, poučiO', da Zemaljsko kraljevstvo zapostavi nebeskomu, podaj, molimo, da i mi ugledajući se u njega prezremo prolazno i sUjedimo vječno, po G. n.","knRef":"Kniewald 1942, str. 542–543 (snimka 272) (OCR)"},"c600ca35b26cf613":{"t":"Mudr 5, 1-5\nČitanje knjige Mudrosti. Pravednici će se junački održati protiv onih koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smest će se od užasnog straha i čudit će se neočekivanom njihovu spasu. Mislit će u sebi očajni i jecajući od duševne boli: To su oni kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima.","kn":"Čitanje knjige mudrosti (5, 1-5). Pravednici će se junački održati protiv -onih, koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smesti će se od užasnog straha 1 čudit će se neočekivanom njihovu spasu. Mislit će u sebi raskajani i jecajući od duševne boli: To su oni, kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima.","knRef":"Kniewald 1942, str. 568–569 (snimka 285) (OCR)"},"157b0d1d6a41242e":{"t":"Ps 88, 6, Ps 20, 4\n<i>Aleluja</i>, <i>aleluja</i>!\n(Ps 88, 6) Nebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>.\n(Ps 20, 4) Gospodine, okrunio si ga krunom od dragoga kamenja, <i>aleluja</i>.","kn":"Aleluja, aleluja! (Ps. 88, 6). Nebesa slave Tvoja čudesa. Gospodine, i Tvoju vjernost sveti pulc Tvoj, aleluja, aleluja! (Ps. 20, 4). Okrunio si ga, Gospodine, krunom dragoga kamenja, aleluja.","knRef":"Kniewald 1942, str. 804–805 (snimka 403) (OCR)"},"80912993d51d297a":{"t":"Lk 14, 26-33\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus narodu: Ako tko dolazi k meni, a ne ostavi svojega oca i majku, ženu i djecu, braću i sestre, pa i samoga sebe, ne može biti moj učenik. I tko ne nosi svoj križ i ne pođe za mnom, ne može biti moj učenik. Jer kad tko od vas odluči sazidati kulu, zar najprije ne sjedne i ne računa, koliko treba troškova da mogne dovršiti, da mu se svi koji vide kako je postavio temelje a nije dovršio, ne stanu rugati: Ovaj je čovjek počeo zidati, a nije mogao dovršiti? Ili koji vladar kad polazi u rat protiv drugoga vladara, zar ne sjedne prije i ne razmišlja, može li se s deset tisuća oprijeti onome koji dolazi protiv njega s dvadeset tisuća? Inače, dok je onaj još daleko, uputit će poslanike i moliti mir. Tako isto nitko od vas koji se ne odreče svega što ima, ne može biti moj učenik.","kn":"t Slijedi sveto evanđelje po Lnki (14, 26-33). U ono vrijeme reče Isus narodu; Ako tko dolazi k meni, a ne mrzi svojega oca i majke i žene i djece i braće i sestara, pa i samoga sebe, ne može biti moj učenik. I tko ne nosi svojega križa i ne ide za mnom, ne može biti moj učenik. Jer tko od vas hoteći graditi kulu, najprije ne sjedne i računa, koliko treba troška, da mogne dovršiti, da mu se svi, koji vide, da je postavio temelje, a nije dovršio, ne počnu rugati i govoriti: Ovaj je čovjek počeo graditi, a nije mogao dovršiti. Ili koji kralj, kad ide ratovati protiv drugoga kralja, ne sjedne prije i promisli, da li se može oprijeti s deset tisuća onomu, koji dolazi na njega s dvadeset tisuća.' Jer će inače, dok je onaj još daleko, uputiti poslanike i moliti za mir. Isto tako nitko od vas, koji se ne odreče svega, što ima, ne može biti moj učenik.","knRef":"Kniewald 1942, str. 542–543 (snimka 272) (OCR)"},"f6559b160ccd64cf":{"t":"Ps 88, 6\nNebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 88, 6). Nebesa slave čudesa Tvoja, Gospodine, i Tvoju vjernost sveti puk Tvoj, aleluja, aleluja.","knRef":"Kniewald 1942, str. 558–559 (snimka 280) (OCR)"},"0741f87b36183013":{"t":"Primi, molimo, Gospodine, naše darove i molitve te nas nebeskim otajstvima očisti i milostivo usliši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, naše darove i molitve, te nas blago usliši i očisti nebeskim otajstvima, Po . G. n.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"3042ea87cdaff402":{"t":"Ps 63, 11\nRaduje se pravednik u Gospodinu i pouzdaje se u njega i hvale se svi koji su pravedna srca, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 63, 11). Veseli se pravednik u Gospodinu i uzda se u njega i raduju se svi, koji su pravedna srca. Aleluja, aleluja.","knRef":"Kniewald 1942, str. 568–569 (snimka 285) (OCR)"},"3b6e3f0bab8b0afc":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine Bože naš, da se tako radujemo vječnim gledanjem tvojih svetih kao što se veselimo sjećanjem na njih po vremenitoj službi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, Gospodine, Bože naž, kao sto se na zemlji radujemo svetkovini Tvojih svetih, tako da se i u vječnosti veselimo gledajući ih, po G. n.","knRef":"Kniewald 1942, str. 544–545 (snimka 273) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
